-- Seed searchable homeowner construction/interior/property FAQs.
-- Idempotent by audience + question so existing admin-edited rows are preserved.

INSERT INTO faq_entries(audience,category,question,answer,sort_order,is_active)
SELECT seed.audience,seed.category,seed.question,seed.answer,seed.sort_order,seed.is_active
FROM (VALUES
  ('homeowner','construction','Why is a lintel necessary above doors and windows?','A lintel bridges the opening and transfers masonry or wall load to the supports on both sides instead of allowing that load to bear directly on the door or window frame. The lintel size, reinforcement and bearing should follow the structural or project drawings rather than a generic rule.',10,TRUE),
  ('homeowner','construction','What causes honeycombing in concrete?','Honeycombing is commonly associated with poor compaction, congested reinforcement, leaking formwork, unsuitable workability, segregation or concrete that cannot properly flow around bars and corners. Prevention starts with a workable approved mix, tight formwork, planned placement and correct vibration. Serious honeycombing should be assessed before repair because depth and location matter.',20,TRUE),
  ('homeowner','construction','Why do cracks form in a new house?','Cracks can come from several different mechanisms: drying or thermal shrinkage, movement between RCC and masonry, settlement, poor curing, plaster workmanship, moisture changes or structural movement. The pattern, width, direction and whether the crack is growing matter. Wide, diagonal, recurring or structural-looking cracks should be reviewed by a qualified professional.',30,TRUE),
  ('homeowner','construction','Which steel is stronger for house construction: Fe500 or Fe500D?','Both designations indicate minimum yield-strength classes under the reinforcement standard, while the D designation is associated with enhanced ductility requirements. “Stronger” alone does not decide what should be used. The structural engineer should specify the grade, bar diameter and detailing for the building. BIS lists IS 1786:2008 for high-strength deformed reinforcement bars.',40,TRUE),
  ('homeowner','construction','Which TMT steel should I use for my house?','Use the grade and bar sizes shown in the approved structural design, from a traceable source that conforms to the specified standard. Do not substitute a different grade simply because it is marketed as premium or stronger. Verify markings, invoices and test documentation where the project quality plan requires it.',50,TRUE),
  ('homeowner','construction','What is the best cement for house construction?','There is no single cement type that is best for every application. Cement selection depends on the approved concrete mix, exposure conditions, structural specification and intended work. OPC, PPC and PSC have different characteristics and relevant BIS standards. Keep cement dry, traceable and within the project specification.',60,TRUE),
  ('homeowner','construction','OPC or PPC: which is better for a house?','Neither is universally better. The appropriate cement depends on the concrete mix, exposure, required early strength, heat development, curing and project specification. Use the cement type approved by the structural engineer or concrete mix designer rather than switching types based only on price or brand.',70,TRUE),
  ('homeowner','construction','M-sand or river sand: which is better for construction?','Quality and grading matter more than the label. Properly manufactured and controlled M-sand can be suitable for concrete, while natural sand also needs acceptable grading and cleanliness. BIS lists IS 383:2016 for coarse and fine aggregates for concrete. Concrete, masonry and plaster may require different aggregate characteristics.',80,TRUE),
  ('homeowner','construction','Red brick or AAC block: which is better for a house?','The better option depends on structural assumptions, wall thickness, local workmanship, services, plaster system, moisture detailing, fixing requirements and budget. AAC is generally lighter, while conventional clay masonry may be familiar to more local crews. Compare the complete wall system rather than only the unit price.',90,TRUE),
  ('homeowner','construction','Why is curing necessary after concreting?','Curing helps concrete retain suitable moisture and temperature conditions for cement hydration and strength development. Poor early curing can increase surface drying and cracking risk. The curing method and duration should follow the concrete specification, cement type, member and weather conditions rather than one universal online number.',100,TRUE),
  ('homeowner','construction','How many days should a slab be cured?','There is no single duration that is correct for every mix, cement type and weather condition. Follow the project specification and engineer’s instructions for the actual concrete used. The important point is to avoid damaging early moisture loss and to maintain the specified curing continuously.',110,TRUE),
  ('homeowner','construction','What happens if too much water is added to concrete at site?','Uncontrolled water addition can change the designed water-cement ratio and may reduce strength, increase permeability, segregation and shrinkage risk. Workability should be managed through the approved mix and admixture process, not by casually adding water at site.',120,TRUE),
  ('homeowner','construction','Why are cover blocks important in RCC?','Cover blocks help maintain the specified distance between reinforcement and the concrete surface. Correct cover supports durability, fire resistance and proper reinforcement position. Cover requirements depend on the member, exposure and design; random stone pieces or incorrect cover can move bars away from their intended position.',130,TRUE),
  ('homeowner','construction','Why is vibration required when concrete is poured?','Proper vibration helps compact fresh concrete, remove trapped air and fill spaces around reinforcement and formwork. Too little vibration can leave voids or honeycombing, while excessive or poorly controlled vibration can contribute to segregation. Use trained placement and compaction practices.',140,TRUE),
  ('homeowner','construction','What is a cold joint in concrete?','A cold joint can occur when fresh concrete is placed against concrete that has already begun to set, so the two placements do not behave like one continuous fresh pour. Construction joints should be planned and treated according to the structural and project specification rather than occurring accidentally from delays.',150,TRUE),
  ('homeowner','construction','What is segregation in concrete and why is it a problem?','Segregation is separation of concrete constituents so the mix is no longer uniform. It can result from unsuitable workability, excessive handling, free fall, over-vibration or poor mix control. Segregated concrete can produce weak, porous or uneven zones and should not simply be covered by finishing work.',160,TRUE),
  ('homeowner','construction','What is bleeding in concrete?','Bleeding is upward movement of water toward the surface of fresh concrete as solids settle. Some bleeding can occur naturally, but excessive bleeding can affect finishing and surface quality. Avoid finishing while bleed water remains and follow the approved concrete and placement process.',170,TRUE),
  ('homeowner','construction','Why is a soil test important before house construction?','Foundation design depends on actual ground conditions, building loads, groundwater and settlement behaviour. Soil can vary significantly even between nearby plots. A neighbour’s footing size is not a reliable substitute for site investigation and structural design.',180,TRUE),
  ('homeowner','construction','Can I copy the foundation design from my neighbour’s house?','No. Even nearby plots can have different fill, soil layers, groundwater or rock depth, and the buildings may have different loads and geometry. Foundation type and size should come from site-specific geotechnical information and structural design.',190,TRUE),
  ('homeowner','construction','Why is a plinth beam provided?','A plinth beam can tie structural elements at plinth level and provide support or load distribution for masonry depending on the design. Its exact role, size and reinforcement depend on the structural system. It should not be added, omitted or resized from a generic detail.',200,TRUE),
  ('homeowner','construction','What is DPC and why is it used?','A damp-proof course is intended to reduce moisture rising through walls or floors by capillary action. Its location and material system should be coordinated with the wall, floor and waterproofing details. DPC cannot compensate for leaking plumbing, poor site drainage or failed external waterproofing.',210,TRUE),
  ('homeowner','construction','Why does dampness appear on new walls?','Possible causes include plumbing leaks, rain penetration, failed waterproofing, rising damp, condensation, wet plaster or trapped construction moisture. Painting over dampness without identifying the moisture source often leads to recurring stains, efflorescence or peeling.',220,TRUE),
  ('homeowner','construction','Why is waterproofing important before tiles are fixed?','Waterproofing is easier to inspect and test before it is hidden by screed, tiles or finishes. Toilets, balconies, terraces and penetrations need correct substrate preparation, detailing, slopes and testing. A decorative tile surface itself is not the waterproofing system.',230,TRUE),
  ('homeowner','construction','Why are slopes important on terraces and balconies?','Adequate falls help water reach drains instead of ponding. Waterproofing should not be expected to compensate for poor drainage geometry. Check outlet locations, thresholds, drain levels and final finish levels as one coordinated detail.',240,TRUE),
  ('homeowner','construction','Why should reinforcement be inspected before slab concreting?','After concrete is poured, bar size, spacing, laps, anchorage, extra reinforcement, cover and embedded services are hidden. A qualified pre-pour inspection against the latest approved structural drawings is therefore an important quality-control step.',250,TRUE),
  ('homeowner','construction','Can electrical conduits be placed inside an RCC slab?','Embedded conduits and sleeves may be part of a coordinated design, but their size, spacing and location should be planned so they do not interfere with reinforcement, slab depth or structural performance. Do not cut or displace reinforcement to make room for unplanned services.',260,TRUE),
  ('homeowner','construction','Why should plumbing pipes be tested before closing walls and floors?','Pressure and leakage testing before concealment makes defects easier to find and repair. Once tiles, ceilings or boxing are complete, the same leak can require destructive access and damage finishes. Keep valves, cleanouts and service routes maintainable.',270,TRUE),
  ('homeowner','construction','Ready-mix concrete or site-mix concrete: which is better?','Either can produce acceptable concrete when properly designed, batched, transported, placed, compacted and cured. Ready-mix offers controlled batching advantages, while small site mixes may be used for appropriate work under supervision. Choose based on structural specification, logistics and quality control rather than a universal ranking.',280,TRUE),
  ('homeowner','construction','What should I check before an RCC slab pour?','Confirm the latest drawings, reinforcement inspection, cover blocks and chairs, formwork stability and levels, openings and sleeves, cleanliness, concrete supply plan, access, manpower, testing arrangements and curing preparation. The engineer or responsible quality person should approve the pour.',290,TRUE),
  ('homeowner','construction','Which material is best for home construction?','There is no single “best material” list that fits every house. Material selection should consider structural design, climate and exposure, availability, workmanship, maintenance, budget and compatibility between systems. Define performance and approved grades first, then compare compliant brands and suppliers.',300,TRUE),
  ('homeowner','interiors','Plywood, MDF or HDHMR: which is best for wardrobes?','The right substrate depends on moisture exposure, finish, machining, hardware loads, screw holding, budget and fabrication method. Plywood, MDF and HDHMR each have suitable applications. Ask for the exact substrate type, grade, thickness, finish and edge treatment in the quotation instead of accepting a generic “premium board” description.',310,TRUE),
  ('homeowner','interiors','What is BWP plywood and where is it useful?','BWP is commonly used as a moisture-resistant plywood category for applications where higher water resistance is desired. Suitability still depends on the exact product standard, exposure, edge sealing, fabrication and installation. Persistent building dampness should be fixed rather than relying on plywood alone.',320,TRUE),
  ('homeowner','interiors','Laminate, acrylic or PU finish: which is better for kitchen shutters?','Laminate is durable and widely available, acrylic can provide a high-gloss manufactured surface, and PU is a painted finish with broad colour and finish flexibility. Cost, scratch visibility, edge treatment, repairability and fabrication quality differ. Choose by use and desired finish rather than a universal ranking.',330,TRUE),
  ('homeowner','interiors','Modular kitchen or carpenter-made kitchen: which should I choose?','Modular systems can offer factory-controlled fabrication, repeatable modules and hardware integration, while skilled site carpentry can offer flexibility for unusual conditions. Compare drawings, substrate, hardware, finishes, edge treatment, installation process, warranty and service—not only the label “modular” or “carpenter.”',340,TRUE),
  ('homeowner','interiors','What should be finalized before ordering a modular kitchen?','Finalize appliance models or dimensions, sink and hob positions, plumbing and electrical points, cabinet layout, storage accessories, countertop, backsplash, shutter finish and hardware. Late appliance changes can force cabinet and service revisions.',350,TRUE),
  ('homeowner','interiors','How should I compare 2BHK interior quotations?','Give every company the same room-by-room scope. Compare actual cabinet dimensions, substrate and thickness, finish, hardware, internal accessories, electrical/civil work, false ceiling, painting, loose furniture, exclusions, taxes, timeline and warranty. Carpet area alone does not define cabinetry cost.',360,TRUE),
  ('homeowner','interiors','Why does interior cost vary so much for the same 2BHK?','Two 2BHK homes can have very different wardrobe lengths, kitchen layouts, ceiling work, finishes, hardware, civil changes and loose furniture. Interior cost is driven by the detailed scope and material level, not only the number of bedrooms.',370,TRUE),
  ('homeowner','interiors','What is the difference between laminate and veneer?','Laminate is a manufactured decorative surface with consistent patterns and practical maintenance. Veneer is a thin layer of natural wood, so grain and colour vary and it usually needs a finishing system. Compare appearance, maintenance, repairability, substrate and budget.',380,TRUE),
  ('homeowner','interiors','Granite or quartz: which is better for a kitchen countertop?','Both can work well when correctly selected and installed. Natural granite varies by slab and may need sealing depending on stone, while engineered quartz offers more controlled appearance but has manufacturer-specific heat and use limitations. Compare thickness, support, joints, edge details, sink cutouts and maintenance.',390,TRUE),
  ('homeowner','interiors','Why is hardware important in modular interiors?','Hinges, drawer channels, lift-up systems and accessories are moving components used repeatedly for years. Hardware grade, load rating, installation accuracy, adjustment and serviceability can affect everyday experience as much as the visible finish.',400,TRUE),
  ('homeowner','interiors','Is a false ceiling necessary for every room?','No. False ceilings can help integrate lighting, conceal services, create levels or support a design concept, but they also reduce clear height and add cost and maintenance considerations. Use them where they solve a functional or aesthetic need rather than by default.',410,TRUE),
  ('homeowner','interiors','What should I plan before making a false ceiling?','Coordinate ceiling levels with AC ducts, sprinklers where applicable, fans, curtain pockets, lighting, access panels and wardrobe heights. Confirm slab leakage or dampness is resolved before concealing the ceiling.',420,TRUE),
  ('homeowner','interiors','How many electrical points should a bedroom have?','There is no universal number. Plan around furniture layout and actual loads: bedside charging, lighting, fan, AC, TV, study/work needs, housekeeping and future flexibility. Circuit design and protection should be handled by a qualified electrical professional.',430,TRUE),
  ('homeowner','interiors','Why should electrical planning happen before interior work?','Wardrobes, TV units, kitchen cabinets, false ceilings and furniture can block or dictate switch and socket positions. Early coordination reduces visible extension wiring, rework and cutting of finished surfaces.',440,TRUE),
  ('homeowner','interiors','Can interiors start if there is dampness on the wall?','It is better to identify and correct the moisture source first. Covering an actively damp wall with cabinetry or decorative panels can trap moisture, damage finishes and hide a continuing leak. Verify plumbing, external seepage, waterproofing and wall dryness before closing the surface.',450,TRUE),
  ('homeowner','interiors','Putty, primer and paint: what is the correct sequence?','The exact system should follow the selected manufacturer’s instructions and substrate condition. In general, the wall must first be sound, dry and repaired; compatible preparation, putty/primer and finish coats then follow the specified paint system with proper drying intervals.',460,TRUE),
  ('homeowner','interiors','How can I make a small apartment feel larger?','Prioritize circulation, correctly scaled furniture, continuous visual lines, useful vertical storage, lighter visual mass, good lighting and fewer unnecessary partitions. Storage planning usually creates more practical value than adding decorative elements to every wall.',470,TRUE),
  ('homeowner','interiors','What should be included in an interior handover checklist?','Check cabinet alignment and operation, hardware adjustment, finish defects, edge sealing, glass/mirror safety, electrical points and lighting, plumbing around sinks, paint touch-ups, accessories, keys, warranties and the final approved scope. Record snags before final closure.',480,TRUE),
  ('homeowner','property','What is RERA and why should a homebuyer check it?','RERA is the real-estate regulatory framework intended to improve transparency, accountability and disclosure in covered projects. For Telangana projects, buyers can verify registration and disclosed project information through the Telangana RERA authority. Whether a particular project requires registration depends on the Act, state rules and project facts.',490,TRUE),
  ('homeowner','property','What is carpet area?','Under the RERA framework, carpet area is the net usable floor area of an apartment, excluding external walls, service shafts, exclusive balcony or verandah area and exclusive open terrace area, while including internal partition walls. Compare homes using clearly disclosed carpet area rather than only marketing terms such as super built-up area.',500,TRUE),
  ('homeowner','property','What is the difference between carpet area, built-up area and super built-up area?','Carpet area focuses on net usable internal floor area as defined under RERA. Built-up area commonly adds wall areas and may include balconies depending on usage, while super built-up or saleable area may also allocate common areas. Because terminology can vary, ask for the exact area statement and RERA disclosures.',510,TRUE),
  ('homeowner','property','What should I verify before paying a token amount for a property?','Before committing money, verify the seller or promoter identity, property details, title and approvals with qualified professionals, RERA registration where applicable, payment terms, refund/cancellation terms and what document the token payment represents. Avoid relying only on verbal assurances.',520,TRUE),
  ('homeowner','property','What is an occupancy certificate and why is it important?','An occupancy certificate generally indicates that the completed building has been assessed by the competent authority for occupancy under applicable approvals and rules. Requirements and terminology vary by authority and project. Buyers should verify the project’s completion/occupancy documentation with the relevant authority and their legal adviser.',530,TRUE),
  ('homeowner','property','What is a completion certificate?','A completion certificate generally relates to completion of construction in accordance with sanctioned plans and applicable requirements. The exact process and document naming can differ by local authority. Verify the specific project’s sanctioned plans, completion and occupancy status rather than relying on marketing statements.',540,TRUE),
  ('homeowner','property','What is an encumbrance certificate?','An encumbrance certificate is commonly used to review registered transactions or encumbrances recorded for a property over a specified period. It is useful but is not a complete substitute for a lawyer’s title search, because every risk or unregistered claim may not appear in one certificate.',550,TRUE),
  ('homeowner','property','Why is legal title verification important before buying property?','Property ownership can involve prior sale deeds, inheritance, mortgages, development agreements, powers of attorney, court matters, acquisition issues and approval conditions. A qualified property lawyer can trace the title chain and review documents instead of relying only on copies supplied by a seller or broker.',560,TRUE),
  ('homeowner','property','Agreement for sale and sale deed: what is the difference?','An agreement for sale records agreed terms and obligations for a future transfer, while a registered sale deed is the conveyance instrument that transfers ownership when executed and registered according to law. The exact legal effect depends on the transaction and jurisdiction, so use qualified legal advice for your purchase.',570,TRUE),
  ('homeowner','property','Ready-to-move or under-construction property: which is better?','The better choice depends on budget, financing, timeline, price, project risk and your need to inspect the finished product. Ready homes allow more direct inspection, while under-construction purchases may offer different payment schedules but require closer review of approvals, RERA disclosures, progress and completion timelines.',580,TRUE),
  ('homeowner','property','What should I check when buying a resale apartment?','Review seller title, prior sale deeds, loan or mortgage closure, society/association dues, property-tax status, sanctioned/actual use, parking and undivided share details where applicable, occupancy/completion records, maintenance history and physical condition. Use independent legal and technical review.',590,TRUE),
  ('homeowner','property','What should I check during a property site visit?','Check access and approach roads, surroundings, noise, drainage, water and power situation, daylight/ventilation, actual unit orientation, construction condition, common areas, parking, lifts, emergency access and the difference between what is shown on plans and what physically exists.',600,TRUE),
  ('homeowner','property','How do I compare property prices in two locations?','Compare like-for-like properties using carpet area, age, floor, orientation, parking, amenities, maintenance, possession status, title/approval quality and actual transaction evidence where available. A quoted price per square foot can be misleading when the area basis differs.',610,TRUE),
  ('homeowner','property','Is the lowest price per square foot always the best property deal?','No. The price basis may use different area definitions, and lower pricing can reflect location, age, legal status, construction quality, floor, access, maintenance or project risk. Compare total acquisition cost and property quality, not one headline rate.',620,TRUE),
  ('homeowner','property','What is the importance of sanctioned plans and approved layouts?','Approved plans and layouts show what the competent authority has permitted for the project or development. Buyers should compare the property being offered with the relevant approvals and verify material deviations or later revisions through appropriate professional and authority checks.',630,TRUE),
  ('homeowner','property','Should I verify a real-estate agent or broker?','Yes. Verify identity, business details and, where the law requires it, RERA agent registration. Also confirm who the agent represents, the brokerage amount, when it becomes payable and whether important statements about approvals, price or possession are documented by the promoter or seller.',640,TRUE),
  ('homeowner','property','What costs should I budget for besides the property price?','Depending on the transaction, additional costs can include stamp duty and registration, taxes, loan charges, legal/technical review, maintenance deposits, utility or association charges, brokerage, interiors and moving costs. Rates and tax treatment can change, so confirm current amounts with the relevant authority and professionals before purchase.',650,TRUE),
  ('homeowner','property','What is a property snag inspection before possession?','A snag inspection records visible defects and incomplete items before handover, such as door/window operation, tile or finish damage, plumbing leaks, electrical points, drainage slopes, cabinetry, paint and common-area issues that are within the inspection scope. Structural or concealed-system concerns require appropriate specialists.',660,TRUE)
) AS seed(audience,category,question,answer,sort_order,is_active)
WHERE NOT EXISTS (
  SELECT 1
  FROM faq_entries existing
  WHERE existing.audience=seed.audience
    AND lower(trim(existing.question))=lower(trim(seed.question))
);
